pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    Receiver r;

    function setUp() public { 
        c = new EBU();
        r = new Receiver();
    }

    // fuzzed params: from address (as uint160), array length and values
    function testFuzz_property(uint160 fromRaw, uint256 len, uint256 seed) public {
        // keep len in a reasonable bound but allow zero which is rejected by require
        uint256 n = bound(len, 0, 6);
        address from = address(uint160(fromRaw));

        // build tos array and v array based on seed to fuzz contents
        address[] memory tos = new address[](n);
        uint256[] memory vs = new uint256[](n);
        for (uint i = 0; i < n; i++) {
            // derive varying addresses/amounts from seed
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
            vs[i] = uint256(keccak256(abi.encodePacked(seed, i, "v"))) % 1000;
        }

        // We route the caddress to our Receiver which implements transferFrom signature and always succeeds.
        address caddress = address(r);

        // Call c.transfer and observe whether it returns true when it completes (no revert).
        bool ok;
        try c.transfer(from, caddress, tos, vs) returns (bool ret) {
            ok = ret; // observe returned value
        } catch {
            ok = false; // treat revert as false for observation
        }

        // GENERAL RULE: For any non-empty tos, when the callee called by C does not revert, C.transfer MUST return true upon successful completion.
        // If n == 0 then C.require will revert; we only assert when n > 0.
        if (n > 0) {
            // the correct contract always returns true here; the mutant returns false for some inputs.
            assertTrue(ok);
        }
    }
}

